  },
  AvgVideoCaption_117618_Content_1 = {
    Text = "অনুমতি ছাড়া পলায়ন, গ্রেপ্তারে প্রতিরোধ, প্রদীপ প্রহরী হত্যা—"
  },
  AvgVideoCaption_117618_Content_10 = {
    Text = "পলাক্স শুধু বাইরের পৃথিবীটা দেখতে চেয়েছিল!"
  },
  AvgVideoCaption_117618_Content_100 = {
    Text = "এখানে এত শব্দ... সবকটা কি আমিই লিখেছি?"
  },
  AvgVideoCaption_117618_Content_101 = {
    Text = "এটা... কী...?"
  },
  AvgVideoCaption_117618_Content_102 = {
    Text = "আর কে... ক্যাস্টর...?"
  },
  AvgVideoCaption_117618_Content_103 = {
    Text = "আমি আর এই শব্দগুলোর দিকে মনোযোগ দিতেও পারছি না..."
  },
  AvgVideoCaption_117618_Content_104 = {
    Text = "আমি খুব দুঃখিত। হঠাৎ করে কেন আমার কান্না পাচ্ছে..."
  },
  AvgVideoCaption_117618_Content_105 = {
    Text = "বেশ, পলাক্স।"
  },
  AvgVideoCaption_117618_Content_106 = {
    Text = "আজ তুমি আমার সঙ্গে নিষ্ঠার সঙ্গে আলোবাহকের পবিত্র কর্মসমূহ আবৃত্তি করবে,"
  },
  AvgVideoCaption_117618_Content_107 = {
    Text = "আর তুমি গভীরভাবে উপলব্ধি করবে তাঁর আলো ও করুণা।"
  },
  AvgVideoCaption_117618_Content_108 = {
    Text = "হ্যাঁ, লণ্ঠন রমণী।"
  },
  AvgVideoCaption_117618_Content_109 = {
    Text = "\"তাঁর আত্মা নির্দোষ নির্মল ভূমিতে প্রত্যাবর্তন করেছে,\""
  },
  AvgVideoCaption_117618_Content_11 = {
    Text = "রূপান্তর আচার অনুষ্ঠান তাকে অসহনীয় পেইন দিয়েছিল..."
  },
  AvgVideoCaption_117618_Content_110 = {
    Text = "\"কিন্তু তাঁর দৃষ্টি এখনো স্নেহভরে এই পৃথিবীর উপর নিবদ্ধ।\""
  },
  AvgVideoCaption_117618_Content_111 = {
    Text = "\"তাঁর আত্মা নির্দোষ নির্মল ভূমিতে প্রত্যাবর্তন করেছে,\""
  },
  AvgVideoCaption_117618_Content_112 = {
    Text = "\"কিন্তু তাঁর দৃষ্টি এখনো স্নেহভরে এই পৃথিবীর উপর নিবদ্ধ।\""
  },
  AvgVideoCaption_117618_Content_113 = {
    Text = "\"তিনি তাঁর নিজ রক্ত, মাংস ও অস্থি দান করেন এই পৃথিবীকে,\""
  },
  AvgVideoCaption_117618_Content_114 = {
    Text = "\"প্রতীক্ষা করেন সেই নির্দোষ আত্মাগুলিকে নির্মল ভূমির পথে পথনির্দেশ করার জন্য,\""
  },
  AvgVideoCaption_117618_Content_115 = {
    Text = "\"...তাঁর সঙ্গে ভাগ করে নেবে নির্মল স্বর্গরাজ্য।\""
  },
  AvgVideoCaption_117618_Content_116 = {
    Text = "\"তিনি তাঁর নিজ রক্ত, মাংস ও অস্থি দান করেন এই পৃথিবীকে,\""
  },
  AvgVideoCaption_117618_Content_117 = {
    Text = "\"প্রতীক্ষা করেন সেই নির্দোষ আত্মাগুলিকে নির্মল ভূমির পথে পথনির্দেশ করার জন্য,\""
  },
  AvgVideoCaption_117618_Content_118 = {
    Text = "\"...তাঁর সঙ্গে ভাগ করে নেবে নির্মল স্বর্গরাজ্য।\""
  },
  AvgVideoCaption_117618_Content_119 = {
    Text = "কাশি..."
  },
  AvgVideoCaption_117618_Content_12 = {
    Text = "মাথা নত কোরো না, ভাই।"
  },
  AvgVideoCaption_117618_Content_120 = {
    Text = "শোনো, পাপী। তোমার দৈনন্দিন খাদ্যের সময় এসেছে।"
  },
  AvgVideoCaption_117618_Content_121 = {
    Text = "অনুগ্রহ করে, জানতে পারি কি... আজ ডিভুস পলাক্স কেমন আছেন...?"
  },
  AvgVideoCaption_117618_Content_122 = {
    Text = "তাঁর পবিত্রতা অবশ্যই সুস্থ আছেন। আজ তিনি লেডি লণ্ঠনের তত্ত্বাবধানে নিষ্ঠার সঙ্গে প্রশিক্ষণ নিচ্ছেন।"
  },
  AvgVideoCaption_117618_Content_123 = {
    Text = "কিন্তু তাতে তোমার কী আসে যায়?"
  },
  AvgVideoCaption_117618_Content_124 = {
    Text = "আপনি প্রতিদিনই এই প্রশ্ন করেন, অথচ আপনি তো কেবল এক..."
  },
  AvgVideoCaption_117618_Content_125 = {
    Text = "উহ... তুমি আবার কে বলেছিলে?"
  },
  AvgVideoCaption_117618_Content_126 = {
    Text = "থাক, কিছু নয়। পাপের জলাশয়ে যে আছে, সে নিঃসন্দেহে পাপী।"
  },
  AvgVideoCaption_117618_Content_127 = {
    Text = "আপনার ভবিষ্যতে ডিভুস সম্পর্কে জিজ্ঞাসা করা বন্ধ করা উচিত।"
  },
  AvgVideoCaption_117618_Content_128 = {
    Text = "সে... তারা কেন আর আমাকে স্মরণ করতে পারে না?"
  },
  AvgVideoCaption_117618_Content_129 = {
    Text = "লণ্ঠন রমণী কি তাদের স্থলে নতুন সলতে বসিয়েছেন...?"
  },
  AvgVideoCaption_117618_Content_13 = {
    Text = "আমি ছিলাম! আমিই প্রদীপ প্রহরীদের ওপর আক্রমণ করেছি!"
  },
  AvgVideoCaption_117618_Content_130 = {
    Text = "পলাক্স... আমার জন্য অপেক্ষা করো..."
  },
  AvgVideoCaption_117618_Content_131 = {
    Text = "যতই সময় লাগুক, আমি সহনশীলতা ধারণ করব। আমি অপেক্ষা করব সেই দিনের জন্য, যখন অবশেষে আমাদের পুনর্মিলন ঘটবে..."
  },
  AvgVideoCaption_117618_Content_14 = {
    Text = "যদি শাস্তি থাকতেই হয়, তবে আমাকে শাস্তি দাও! না... না!"
  },
  AvgVideoCaption_117618_Content_15 = {
    Text = "আমরা ত্যাগ করতে পারি না... স্বাধীনতার জন্য।"
  },
  AvgVideoCaption_117618_Content_16 = {Text = "আঃ—"},
  AvgVideoCaption_117618_Content_17 = {
    Text = "আআআর্ঘ—! পলাক্স! ক্‌খ...!"
  },
  AvgVideoCaption_117618_Content_18 = {
    Text = "ওহ, আমি প্রায় ভুলেই গিয়েছিলাম যে আমাদের দিভুস ক্যাস্টর তো আগেই বেশ... ক্ষতিগ্রস্ত।"
  },
  AvgVideoCaption_117618_Content_19 = {
    Text = "তাকে নিরাময় করব? প্রয়োজন নেই। ক্যাস্টরকে পাপের জলাশয়ে নিক্ষেপ করো।"
  },
  AvgVideoCaption_117618_Content_2 = {
    Text = "এটাই কি সেই কৃতজ্ঞতা, যা আমাদের দিভুস গির্জাকে প্রদান করে?"
  },
  AvgVideoCaption_117618_Content_20 = {
    Text = "পবিত্র রক্ত তার পাপ ধুয়ে নিয়ে যাবে।"
  },
  AvgVideoCaption_117618_Content_21 = {
    Text = "মলিনতা গলে গিয়ে স্রোতে ভেসে গেলে তবেই সে যেতে পারবে।"
  },
  AvgVideoCaption_117618_Content_22 = {
    Text = "ভা...ই..."
  },
  AvgVideoCaption_117618_Content_23 = {
    Text = "ঠিক আছে। এরপর, আমাদের অবশিষ্ট দিভুসদের সময় হয়েছে"
  },
  AvgVideoCaption_117618_Content_24 = {
    Text = "আলোবাহকের শিক্ষার একটি সম্পূর্ণ পর্যালোচনা শুরু করার।"
  },
  AvgVideoCaption_117618_Content_25 = {
    Text = "আজ থেকে, পবিত্র দিব্যবাণী বোঝার জন্য আমি নিজ হাতে তোমাকে শিক্ষা দেব।"
  },
  AvgVideoCaption_117618_Content_26 = {Text = "..."},
  AvgVideoCaption_117618_Content_27 = {
    Text = "আমি আসলে তোমাকে সম্পূর্ণ বুঝি, এবং তোমার আত্মাকে আমি শ্রদ্ধা করি।"
  },
  AvgVideoCaption_117618_Content_28 = {
    Text = "পলাক্স, তুমি সত্যিই জ্ঞানী আর ভালো সন্তান।"
  },
  AvgVideoCaption_117618_Content_29 = {
    Text = "মনে হচ্ছে এই মূল্যবান প্রজ্ঞা সঠিকভাবে প্রয়োগ করা হয়নি,"
  },
  AvgVideoCaption_117618_Content_3 = {
    Text = "এখনই বলো: কার পরিকল্পনা ছিল এটা?"
  },
  AvgVideoCaption_117618_Content_30 = {
    Text = "বরং তুমি প্রদীপবাহকের সেবার দায়িত্ব থেকে পালিয়ে গেলে"
  },
  AvgVideoCaption_117618_Content_31 = {
    Text = "ওই রূপান্তর আচার অনুষ্ঠানগুলো সত্যিই তোমাকে অতিরিক্ত পেইন দিয়েছে, তাই না?"
  },
  AvgVideoCaption_117618_Content_32 = {
    Text = "তবু, আলোবাহক স্বয়ং আলো বপন করতে অগণন পেইন সহ্য করেছিলেন,"
  },
  AvgVideoCaption_117618_Content_33 = {
    Text = "এমনকি মানবজাতির পাপ শুদ্ধ করতে নিজের মাংসও উৎসর্গ করেছিলেন।"
  },
  AvgVideoCaption_117618_Content_34 = {
    Text = "তুমি এখনো তাঁর করুণা কিংবা প্রয়োজনীয় মহান উৎসর্গ পুরোপুরি অনুধাবন করতে পারো না, আর সেটাই স্বাভাবিক।"
  },
  AvgVideoCaption_117618_Content_35 = {
    Text = "মরণশীলেরা যখন দেবতার কার্যকলাপ বোঝার চেষ্টা করে, তারা প্রায়ই বিভ্রান্ত ও দুর্বল হয়ে পড়ে।"
  },
  AvgVideoCaption_117618_Content_36 = {
    Text = "তোমার যা প্রয়োজন, তা হলো আরও গভীর শিক্ষা এবং অন্তর্দৃষ্টি..."
  },
  AvgVideoCaption_117618_Content_37 = {
    Text = "হায়। তদুপরি, ক্যাস্টর এখনো মারাত্মকভাবে আহত এবং সংকটকালীন বিজ্ঞপ্তিতে রয়েছে।"
  },
  AvgVideoCaption_117618_Content_38 = {
    Text = "তোমার ভাইয়ের পাপ যত দ্রুত সম্ভব শুদ্ধিকরণ করার জন্য,"
  },
  AvgVideoCaption_117618_Content_39 = {
    Text = "তোমাকে অবিলম্বে দিভুসের সমস্ত দায়িত্ব পুনরায় কাঁধে তুলে নিতে হবে।"
  },
  AvgVideoCaption_117618_Content_4 = {
    Text = "হ্যাঁ..."
  },
  AvgVideoCaption_117618_Content_40 = {
    Text = "...আমি ক্ষমাপ্রার্থী, লেডি লণ্ঠন। আমি শিখব।"
  },
  AvgVideoCaption_117618_Content_41 = {
    Text = "ঠিক আছে। তবে আমার সঙ্গে এসো, আলোবাহকের পবিত্র কর্মসমূহ একনিষ্ঠভাবে উচ্চারণ করো,"
  },
  AvgVideoCaption_117618_Content_42 = {
    Text = "এবং তিনি যে উপদেশ আমাদের দান করেছেন, তা গভীরভাবে মননে ধারণ করো।"
  },
  AvgVideoCaption_117618_Content_43 = {
    Text = "...জি, লেডি লণ্ঠন।"
  },
  AvgVideoCaption_117618_Content_44 = {
    Text = "\"তিনি এক অনন্ত প্রদীপ হাতে নিয়ে, অন্ধকারে আচ্ছন্ন পৃথিবীর বুকে হেঁটে চলেন।\""
  },
  AvgVideoCaption_117618_Content_45 = {
    Text = "\"তিনি এক অনন্ত প্রদীপ হাতে নিয়ে, অন্ধকারে আচ্ছন্ন পৃথিবীর বুকে হেঁটে চলেন।\""
  },
  AvgVideoCaption_117618_Content_46 = {
    Text = "\"তিনি পাপের সাগরের দিকে দৃষ্টি মেললেন, আর শোকের অশ্রু ঝরালেন,\""
  },
  AvgVideoCaption_117618_Content_47 = {
    Text = "\"এবং তাই তিনি নিজের মাংস চিরে খুললেন, ঝরতে দিলেন কালো রক্ত...\""
  },
  AvgVideoCaption_117618_Content_48 = {
    Text = "\"তিনি পাপের সাগরের দিকে দৃষ্টি মেললেন, আর শোকের অশ্রু ঝরালেন,\""
  },
  AvgVideoCaption_117618_Content_49 = {
    Text = "\"এবং তাই তিনি নিজের মাংস চিরে খুললেন, ঝরতে দিলেন কালো রক্ত...\""
  },
  AvgVideoCaption_117618_Content_5 = {
    Text = "ওটা ছিল... ওটা ছিল আমারই।"
  },
  AvgVideoCaption_117618_Content_50 = {
    Text = "আহ! ভাই! তুমি কেন নিজের হাত চিরে খুলে দিলে?!"
  },
  AvgVideoCaption_117618_Content_51 = {
    Text = "সবটাই আমার দোষ; আচার অনুষ্ঠানে তোমার স্থলাভিষিক্ত হওয়ার ক্ষমতা আমার নেই।"
  },
  AvgVideoCaption_117618_Content_52 = {
    Text = "কিন্তু অন্তত আমাকে তোমার পেইন ভাগ করে নিতে দাও..."
