  AvgVideoCaption_117618_Content_53 = {Text = "ভাই!"},
  AvgVideoCaption_117618_Content_54 = {
    Text = "উঃ... ধ্যাত, মাথাটা যেন বিভাজন হয়ে যাচ্ছে।"
  },
  AvgVideoCaption_117618_Content_55 = {
    Text = "ওই নারীটা... সে নিশ্চয়ই আমার সঙ্গে কিছু করেছে।"
  },
  AvgVideoCaption_117618_Content_56 = {
    Text = "আমার ভাইয়ের মুখের ছবি কেন এত ঝাপসা হয়ে যাচ্ছে...?"
