  },
  AvgVideoCaption_117618_Content_66 = {
    Text = "\"তাঁর রক্ত পাপ দূর করে, মুক্তি দেয় প্রতিটি আত্মা।\""
  },
  AvgVideoCaption_117618_Content_67 = {
    Text = "\"কিন্তু পৃথিবী এখনো অন্তহীন অন্ধকারে মোড়া,\""
  },
  AvgVideoCaption_117618_Content_68 = {
    Text = "\"তাই তিনি সেই পবিত্র শিখা দিয়ে নিজের দেহকাঠামোই প্রজ্বলিত করলেন...\""
  },
  AvgVideoCaption_117618_Content_69 = {
    Text = "\"কিন্তু পৃথিবী এখনো অন্তহীন অন্ধকারে মোড়া,\""
