  },
  AvgVideoCaption_124223_Content_57 = {
    Text = "এখানে আছে চাপ কমানোর প্রাচীন বস্তু, আর আছে অন্য জগতের শোবার সময়ের গল্প।"
  },
  AvgVideoCaption_124223_Content_58 = {
    Text = "আছে সকলে‌র প্রায়-ধসে-পড়া প্রলাপ, ঘুমপাড়ানি গান হয়ে।"
  },
  AvgVideoCaption_124223_Content_59 = {
    Text = "মাঝে মাঝে দেখি, অন্যরা একে অপরকে মারতে মারতে মাথা ফাটিয়ে রক্ত ঝরাচ্ছে, ভীষণ মজা লাগে।"
  },
  AvgVideoCaption_124223_Content_6 = {
    Text = "কখনো ভাবিনি, ডায়েরি লেখার মতো বিরক্তিকর কিছু আমি করব..."
  },
  AvgVideoCaption_124223_Content_60 = {
    Text = "এক চুমুক বাড়তি পানি বা এক কামড় বাড়তি রুটির জন্য কীসের এত লড়াই, আমি বুঝি না।"
  },
  AvgVideoCaption_124223_Content_61 = {
    Text = "হয়তো এসব জিনিস আর ততটা গুরুত্বপূর্ণ নয়।"
  },
  AvgVideoCaption_124223_Content_62 = {
    Text = "তারা শুধু তাদের বুকের ভেতরের আতঙ্ক উগরে দেওয়ার একটা কারণ চায়।"
  },
  AvgVideoCaption_124223_Content_63 = {
    Text = "নিঃসন্দেহে করুণ আর করুণারও অতীত।"
  },
  AvgVideoCaption_124223_Content_64 = {
    Text = "「সেই ঘটনাটা」 ঘটার পর এই প্রথম আমি ডায়েরি লিখছি।"
  },
  AvgVideoCaption_124223_Content_65 = {
