  AvgVideoCaption_124223_Content_66 = {
    Text = "সে কুয়াশায় ক্ষয়প্রাপ্ত হয়েছিল, যেন এক ফোঁটা জল সাগরে মিশে গিয়ে সম্পূর্ণ মিলিয়ে যায়।"
  },
  AvgVideoCaption_124223_Content_67 = {
    Text = "এটা কুয়াশা ক্ষয়গ্রাসের দ্বিতীয় ঘটনা, উচ্চমাত্রার সতর্কতার যোগ্য।"
  },
  AvgVideoCaption_124223_Content_68 = {
    Text = "আমাকে আরও রসদ জোগাড় করতে হবে এবং অবশিষ্ট জীবিত প্রত্যাবর্তনকারীদের কুয়াশার বাইরে নেতৃত্ব দিতে হবে।"
  },
  AvgVideoCaption_124223_Content_69 = {
    Text = "একাদশ দিন, আমি কিছু শুকনো হরিণের মাংস, অঙ্কুরিত আলু আর বেকন পেয়েছি।"
  },
  AvgVideoCaption_124223_Content_7 = {
    Text = "থাক, আগেভাগে একটা তদন্ত প্রতিবেদন লিখছি—এভাবেই ধরে নিলেই হয়।"
  },
  AvgVideoCaption_124223_Content_70 = {
    Text = "বেকন সুস্বাদু, কিন্তু র‍্যাভেনলগ স্টিউড মাছের মতো ভালো নয়।"
  },
  AvgVideoCaption_124223_Content_71 = {
