  AvgVideoCaption_124223_Content_83 = {
    Text = "চার্লসের আত্মা ভেঙে চুরমার হয়ে গেল।"
  },
  AvgVideoCaption_124223_Content_84 = {
    Text = "আত্মহত্যা।"
  },
  AvgVideoCaption_124223_Content_85 = {
    Text = "18তম দিন, কিছুই পাওয়া গেল না।"
  },
  AvgVideoCaption_124223_Content_86 = {
    Text = "একুশতম দিন, শুকনো হরিণের মাংস, অঙ্কুরিত আলু... আবারও।"
  },
  AvgVideoCaption_124223_Content_87 = {
