  AvgVideoCaption_124223_Content_92 = {
    Text = "তাদের কুয়াশার সীমানার বাইরে পৌঁছে দাও, তারপর স্বদেশে ফেরার কথা ভাবা যাবে।"
  },
  AvgVideoCaption_124223_Content_93 = {
