  },
  AvgVideoCaption_124223_Content_96 = {
    Text = "তাহলে তাদের ফিরিয়ে দাও, আমি তোমাকে আদেশ দিচ্ছি, তাদের ফিরিয়ে দাও!"
  },
  AvgVideoCaption_124223_Content_97 = {
    Text = "বাঁচাতে পারি না… কেন একজনকেও বাঁচাতে পারি না…"
