  },
  AvgVideoCaption_126905_Content_11 = {
    Text = "যা কিছু তুমি ঘৃণা করো, তাকে মিথ্যা বানানো যায়।"
  },
  AvgVideoCaption_126905_Content_110 = {
    Text = "সম্পূর্ণভাবে, সম্পূর্ণভাবে, এই দাসীর কাছে এসো\nসম্পূর্ণভাবে, সম্পূর্ণভাবে, মায়ের কাছে এসো"
  },
  AvgVideoCaption_126905_Content_111 = {
