    Text = "এখন..."
  },
  AvgVideoCaption_126905_Content_34 = {
    Text = "আমরা কোথায় থেমেছিলাম?"
  },
  AvgVideoCaption_126905_Content_35 = {
    Text = "জনতার বেছে নেওয়ার সময় দ্রুতই এসে গেল।"
  },
  AvgVideoCaption_126905_Content_36 = {
    Text = "এই দিনে,"
  },
  AvgVideoCaption_126905_Content_37 = {
    Text = "এক বিদেশি বণিক এক বিরল বস্তু নিয়ে এলো।"
  },
  AvgVideoCaption_126905_Content_38 = {
    Text = "এর ছিল চারটি চটপটে, সরু খুর,"
  },
  AvgVideoCaption_126905_Content_39 = {
    Text = "সঙ্গে ছিল এক জোড়া লম্বা শিং, আর বরফফুলের দাগে ছোপছোপ এক কোট।"
  },
  AvgVideoCaption_126905_Content_4 = {
    Text = "আরও কাছে এসো।"
  },
  AvgVideoCaption_126905_Content_40 = {
    Text = "মন্ত্রী বললেন:"
  },
  AvgVideoCaption_126905_Content_41 = {
    Text = "「মহারাজ, আমি আপনার জন্য এক সহস্র-মাইল অশ্ব পেয়েছি—অতুলনীয় এক ঘোড়া।」"
  },
  AvgVideoCaption_126905_Content_42 = {
    Text = "আচ্ছা, অবশ্যই ওটা ঘোড়া ছিল না।"
  },
  AvgVideoCaption_126905_Content_43 = {
    Text = "রাজাও ঠিক তাই-ই বলেছিলেন।"
  },
  AvgVideoCaption_126905_Content_44 = {
    Text = "「আমার প্রিয় মন্ত্রী, আপনি ঠাট্টা করছেন। এটি স্পষ্টতই একটি হরিণ।」"
  },
  AvgVideoCaption_126905_Content_45 = {
    Text = "নিচের দরবারিরা নিজেদের মধ্যে ফিসফিস করে, গুনগুনিয়ে কথা বলতে লাগল।"
  },
  AvgVideoCaption_126905_Content_46 = {
    Text = "কিন্তু মন্ত্রী কেবল শান্ত চোখে রাজ্যের দৃষ্টির সঙ্গে চোখ মিলিয়ে বললেন,"
  },
  AvgVideoCaption_126905_Content_47 = {
    Text = "「পবিত্র প্রভু, এটি একটি ঘোড়া।」"
  },
  AvgVideoCaption_126905_Content_48 = {
    Text = "যারা মন্ত্রীর পাশে দাঁড়িয়েছিল, তারাও সুর মিলিয়ে বলতে শুরু করল।"
  },
  AvgVideoCaption_126905_Content_49 = {
    Text = "「নিশ্চয়ই, এটি একটি ঘোড়া।」"
  },
  AvgVideoCaption_126905_Content_5 = {
    Text = "আমি তোমার জন্য একটি মেঘ ছিঁড়ে আনব, যাতে তুমি বিশ্রাম নিতে পারো..."
  },
  AvgVideoCaption_126905_Content_50 = {
    Text = "「একটি ঘোড়া ঠিক এমনই দেখতে হয়।」"
  },
  AvgVideoCaption_126905_Content_51 = {
    Text = "「কি অপূর্ব অশ্ব! এমন চমৎকার বাহন পাওয়ায় আপনাকে অভিনন্দন, মহামান্য।」"
  },
  AvgVideoCaption_126905_Content_52 = {
    Text = "মন্ত্রী의 নাগালের আতঙ্কে হোক, বা চাটুকারদের বেপরোয়া উল্লাসের কারণেই হোক,"
  },
  AvgVideoCaption_126905_Content_53 = {
    Text = "যে অল্প কয়েকটি ভয়েস বলছিল এটি হরিণ, তাদের দ্রুতই জোয়ারের মতো স্রোত ডুবিয়ে দিল।"
  },
  AvgVideoCaption_126905_Content_54 = {
    Text = "আর সেই জোয়ারের মাঝখানে, সবার চোখের সামনে, হরিণটি বদলাতে শুরু করল।"
  },
  AvgVideoCaption_126905_Content_55 = {
    Text = "প্লামফুলের দাগগুলো ফেটে বিভাজন হয়ে গেল; শিংগুলো নরম হয়ে শুকিয়ে গিয়ে ঝরে পড়ল।"
  },
  AvgVideoCaption_126905_Content_56 = {
    Text = "তার অস্থিগুলো লম্বা হতে হতে কঁকিয়ে উঠল।"
  },
  AvgVideoCaption_126905_Content_57 = {
    Text = "তার চামড়া থেকে চুঁইয়ে পড়া রক্ত জমাট বেঁধে খুরের ফাঁকে জমল, শক্ত হয়ে ভারী খুরে রূপ নিল।"
  },
  AvgVideoCaption_126905_Content_58 = {
    Text = "এই রক্তমাখা বিকৃত দানবটি প্রাসাদের হলঘরে দাঁড়িয়ে ছিল,"
  },
  AvgVideoCaption_126905_Content_59 = {
    Text = "ছেড়ে দিচ্ছিল এক গ্রোটেস্ক, বেসুরো হ্রেষাধ্বনি।"
  },
  AvgVideoCaption_126905_Content_6 = {
    Text = "হ্যাঁ, স্বপ্নহীন দেশে এমন বিষয় আর বিশেষ বিস্ময়ের নয়।"
  },
  AvgVideoCaption_126905_Content_60 = {
    Text = "মন্ত্রী শান্ত ও স্থির ভঙ্গিতে তাকে আদর করছিলেন।"
  },
  AvgVideoCaption_126905_Content_61 = {
    Text = "রাজা সিংহাসনে বসেই আতঙ্কে জমে গেলেন।"
  },
  AvgVideoCaption_126905_Content_62 = {
    Text = "মানুষ অবশেষে বুঝল, তাদের কোথায় দাঁড়াতে হবে।"
  },
  AvgVideoCaption_126905_Content_63 = {
    Text = "সেই দিন থেকে,"
  },
  AvgVideoCaption_126905_Content_64 = {
    Text = "ঘোড়ায়-পরিণত হরিণের বিকৃত ছায়া রাজাকে অনুসরণ করল।"
  },
  AvgVideoCaption_126905_Content_65 = {
    Text = "কেউ আর পবিত্র প্রভুর খোঁজ রাখল না।"
  },
  AvgVideoCaption_126905_Content_66 = {
    Text = "কেউ আর তার ভাবনার পরোয়া করল না।"
  },
  AvgVideoCaption_126905_Content_67 = {
    Text = "দানব যখন তাকে যন্ত্রণা দিচ্ছিল, তার গলায় চেপে ধরা আর্তনাদ কেউই কানে নিল না।"
  },
  AvgVideoCaption_126905_Content_68 = {
    Text = "কারণ তা কামনা থেকে জন্মাক, আতঙ্ক থেকে, বা শীতল গণনা থেকে,"
  },
  AvgVideoCaption_126905_Content_69 = {
    Text = "জনতা দাঁড়াল মন্ত্রীর পাশে।"
  },
  AvgVideoCaption_126905_Content_7 = {
    Text = "এর গন্ধ আছে; এটি কোমল আর শীতল।"
  },
  AvgVideoCaption_126905_Content_70 = {
    Text = "তিনি বলেছিলেন এটি ঘোড়া, তাই সেটাই সত্যি হলো। হরিণ হলেও তা ঘোড়া।"
  },
  AvgVideoCaption_126905_Content_71 = {
    Text = "এভাবেই, রাজা রাজার আসনেই রইলেন..."
  },
  AvgVideoCaption_126905_Content_72 = {
    Text = "শুধু এই জন্যই যে তিনি কখনো মুখ খুলে বলেননি, রাজা আর বেঁচে নেই।"
  },
  AvgVideoCaption_126905_Content_73 = {
    Text = "ছোট জেসমিন, সেই গল্পে তুমি কী স্বাদ পেয়েছিলে?"
  },
  AvgVideoCaption_126905_Content_74 = {
    Text = "হেহ হেহ... হাহাহাহা!"
  },
  AvgVideoCaption_126905_Content_75 = {
    Text = "আমার অমূল্য বাওবেই,"
  },
  AvgVideoCaption_126905_Content_76 = {
    Text = "আমার সবচেয়ে প্রিয়, স্নেহের সন্তান।"
  },
  AvgVideoCaption_126905_Content_77 = {
    Text = "হ্যাঁ... সেটি মিষ্টতা।"
  },
  AvgVideoCaption_126905_Content_78 = {
    Text = "যতক্ষণ বহুসংখ্যক জনতা তোমার পাশে থাকে,"
  },
  AvgVideoCaption_126905_Content_79 = {
    Text = "যতক্ষণ শক্তি তোমার মুঠোর ভেতরে থাকে,"
  },
  AvgVideoCaption_126905_Content_8 = {
    Text = "হ্যাঁ, আমার মধুর প্রিয়, অবশ্যই এটি একটি মেঘ।"
  },
  AvgVideoCaption_126905_Content_80 = {
    Text = "সত্য, মিথ্যা—এমনকি সঠিক আর ভুলও—শুধু তোমার খেয়ালের ওপরেই টিকে থাকে।"
  },
  AvgVideoCaption_126905_Content_81 = {
    Text = "রাজা আর প্রজার ইচ্ছা, তারা যে সব আতঙ্কের মুখোমুখি হয়..."
  },
  AvgVideoCaption_126905_Content_82 = {
    Text = "তারা কারওই কিছু নয়, তুচ্ছ।"
  },
  AvgVideoCaption_126905_Content_83 = {
    Text = "এই শহর হবে তোমার খেলনা।"
  },
  AvgVideoCaption_126905_Content_84 = {
    Text = "এই বিশ্ব... হবে তোমার খেলনা।"
  },
  AvgVideoCaption_126905_Content_85 = {
    Text = "তুমি ভীষণ ক্লান্ত।"
  },
  AvgVideoCaption_126905_Content_86 = {
    Text = "তুমি কোনো নিশ্চিত জিনিস আঁকড়ে ধরতে চাও, আর কেনই বা চাইবে না?"
  },
  AvgVideoCaption_126905_Content_87 = {
    Text = "শক্তি মানেই নিরাপত্তা। শক্তি মানেই মাধুর্য, আমার ছোট্ট জুঁইফুল।"
  },
  AvgVideoCaption_126905_Content_88 = {
    Text = "তুমি যদি বিশ্বাস করো ওটা মেঘ, তবে ওটাই মেঘ।"
  },
  AvgVideoCaption_126905_Content_89 = {
    Text = "তুমি যদি চাও কেউ তোমার পাশে থাকুক, তবে সে সেখানেই থাকবে, চিরকাল, অনন্তকাল।"
  },
  AvgVideoCaption_126905_Content_9 = {
    Text = "চুপ—"
  },
  AvgVideoCaption_126905_Content_90 = {Text = "হুঁ?"},
  AvgVideoCaption_126905_Content_91 = {
    Text = "আহ... এটা কি তোমার জন্য বেশি জটিল হয়ে গেল?"
  },
  AvgVideoCaption_126905_Content_92 = {
    Text = "এত ছোট, নরম, ভঙ্গুর একটুখানি সত্তা।"
  },
  AvgVideoCaption_126905_Content_93 = {
    Text = "শুধু একটি আপন ঠিকানার জন্য,"
  },
  AvgVideoCaption_126905_Content_94 = {
    Text = "শুধু নিঃসঙ্গতা থেকে পালানোর জন্য,"
  },
  AvgVideoCaption_126905_Content_95 = {
    Text = "তুমি যেকোনো কিছু করতে পারতে।"
  },
  AvgVideoCaption_126905_Content_96 = {
    Text = "এসো। এসো, আমার বুকে চলে এসো।"
  },
  AvgVideoCaption_126905_Content_97 = {
    Text = "স্বপ্নহীন দেশের বাসিন্দাদের কোনো স্বপ্নের প্রয়োজন নেই।"
  },
  AvgVideoCaption_126905_Content_98 = {
    Text = "বাস্তবতার সবকিছুই তুমি পাবে।"
  },
  AvgVideoCaption_126905_Content_99 = {
    Text = "তুমি কীতে বিশ্বাস করো, আমার ছোট জেসমিন?"
  },
  AvgVideoCaption_131662_Content_1 = {
    Text = "ঠান্ডা... কত ঠান্ডা..."
  },
  AvgVideoCaption_131662_Content_10 = {
    Text = "চেতনা সম্ভবত এখনো @3 মানসিক স্থান থেকে সম্পূর্ণ বিচ্ছিন্ন হয়নি।"
  },
  AvgVideoCaption_131662_Content_100 = {
    Text = "বিপর্যয়... বিপর্যয়... বিপর্যয়..."
  },
  AvgVideoCaption_131662_Content_101 = {
    Text = "দৌড়াও, দৌড়াও!"
  },
  AvgVideoCaption_131662_Content_102 = {
    Text = "এখনই যাও, এখনই যাও!"
  },
  AvgVideoCaption_131662_Content_103 = {
    Text = "বড় আগুনের গোলা..."
  },
  AvgVideoCaption_131662_Content_104 = {
    Text = "ত্রিশতম বার..."
  },
  AvgVideoCaption_131662_Content_105 = {
    Text = "চল্লিশতম?"
  },
  AvgVideoCaption_131662_Content_106 = {
    Text = "দৌড়াও... বিকৃত,"
  },
  AvgVideoCaption_131662_Content_107 = {
    Text = "খুব ঠান্ডা... খুব ঠান্ডা..."
  },
  AvgVideoCaption_131662_Content_108 = {
    Text = "বন্ধু... কোয়ালসি..."
  },
  AvgVideoCaption_131662_Content_109 = {
    Text = "দুঃখিত……দুঃখিত……"
  },
  AvgVideoCaption_131662_Content_11 = {
    Text = "@3 দিন পর, পরীক্ষিত ব্যক্তি ভাষাগত বোধশক্তি প্রদর্শন করে।"
  },
  AvgVideoCaption_131662_Content_110 = {
    Text = "ঘূর্ণাবর্ত। ঘূর্ণাবর্তে যেতে হবে।"
  },
  AvgVideoCaption_131662_Content_111 = {
    Text = "ঘূর্ণাবর্ত... তাদের বাঁচাতে যেতে হবে।"
  },
  AvgVideoCaption_131662_Content_112 = {
    Text = "ভোর্তিচে... তাদের বাঁচাতে হবে..."
  },
  AvgVideoCaption_131662_Content_113 = {
    Text = "ঠান্ডা, ঠান্ডা!"
  },
  AvgVideoCaption_131662_Content_114 = {
    Text = "শব্দটা কত ভয়ংকর জোরে!"
  },
  AvgVideoCaption_131662_Content_115 = {
    Text = "কিন্তু..."
  },
  AvgVideoCaption_131662_Content_116 = {
    Text = "ভোর্তিচে চাইবে! তাদের বাঁচাবে!"
  },
  AvgVideoCaption_131662_Content_117 = {
    Text = "জাগরণকারী O-1841"
  },
  AvgVideoCaption_131662_Content_118 = {
    Text = "জাগরণকারী O-1841"
  },
  AvgVideoCaption_131662_Content_119 = {
    Text = "তুমি কি আমাকে শুনতে পাচ্ছ?"
  },
  AvgVideoCaption_131662_Content_12 = {
    Text = "মিথাগ কলেজের জাগরণ বিভাগ যোগাযোগ প্রোটোকল শুরু করে।"
  },
  AvgVideoCaption_131662_Content_120 = {
    Text = "যদিও অনুভব করা যায় না,"
  },
  AvgVideoCaption_131662_Content_121 = {
    Text = "@4 সেন্সর দেখাচ্ছে তোমার শক্তি অজান্তেই চারপাশের সব পদার্থকে বিকৃত করছে।"
  },
  AvgVideoCaption_131662_Content_122 = {
    Text = "আমাদের সতর্ক করার জন্য ধন্যবাদ।"
  },
  AvgVideoCaption_131662_Content_123 = {
    Text = "যদি তুমি সহযোগিতা করতে রাজি থাকো,"
