  },
  AvgVideoCaption_18626_Content_8 = {
    Text = "আইগিস তার চোখ বুজে ফেলে, অনুভব করে নিজেকে ক্রমশ হালকা থেকে হালকাতর হয়ে উঠছে। তার পেছনে, রামোনা মরিয়া হয়ে রাতের আকাশের দিকে হাতের কার্ড বাড়িয়ে দেয়।"
