  AvgVideoCaption_45044_Content_1 = {
    Text = "এক অদৃশ্য প্লেগ আমাদের গ্রাস করেছে"
  },
  AvgVideoCaption_45044_Content_10 = {
    Text = "\"আপনি কি আমাদের আপনার মাংস দেবেন?\""
