  AvgVideoCaption_72086_Content_3 = {
    Text = "নক্ষত্রসমূহের সমন্বয়ের সেই মুহূর্ত দ্রুত এগিয়ে আসছে"
  },
  AvgVideoCaption_72086_Content_30 = {
    Text = "এই এক সত্তার ফরমানেই, লেমুরিয়া চিরকাল অটল থাকবে—অভঙ্গুর, অবনতিহীন, অবিনশ্বর"
