  },
  AvgVideoCaption_76210_Content_1 = {
    Text = "উইঙ্কল, ফোনোগ্রাফটা শুরু করো।"
  },
  AvgVideoCaption_76210_Content_10 = {
    Text = "সর্বোত্তম পদক্ষেপ হলো আমি নিজেই এই মস্তিষ্কের জারের ওপর অস্ত্রোপচার করি—এর পুষ্টি-দ্রবণের সঙ্গে সংযোগের ধরন বদলে দিই।"
  },
  AvgVideoCaption_76210_Content_11 = {
    Text = "জোরপূর্বক মস্তিষ্কের কার্যকলাপ বাড়িয়ে রক্ষকের চেতনাকে জাগরণে আনা।"
  },
  AvgVideoCaption_76210_Content_12 = {
    Text = "প্রিয় কুকুরছানা, ভয় পাওয়ার কিছুই নেই।"
  },
  AvgVideoCaption_76210_Content_13 = {
    Text = "ভালো। যন্ত্রপাতি প্রস্তুত। বেরিয়ে আসো।"
  },
  AvgVideoCaption_76210_Content_14 = {
    Text = "কি সুন্দর মস্তিষ্কের খাঁজ।"
  },
  AvgVideoCaption_76210_Content_15 = {
    Text = "অতিরিক্ত অশুদ্ধতা অপসারণ করছি..."
  },
  AvgVideoCaption_76210_Content_16 = {
    Text = "মস্তিষ্কের কর্টেক্সের পবিত্রতা পুনরুদ্ধার করছি।"
  },
  AvgVideoCaption_76210_Content_17 = {
    Text = "এই নাও..."
  },
  AvgVideoCaption_76210_Content_18 = {
    Text = "কডেট নিউক্লিয়াস।"
  },
  AvgVideoCaption_76210_Content_19 = {
    Text = "লেন্টিফর্ম নিউক্লিয়াস।"
  },
  AvgVideoCaption_76210_Content_2 = {
    Text = "এর চেতনা কি এখনও ঠিকমতো মস্তিষ্কের ট্যাঙ্কের সঙ্গে সংযোগ স্থাপন করতে পারছে না?"
  },
  AvgVideoCaption_76210_Content_20 = {
    Text = "অ্যামিগডালা।"
