  AvgVideoCaption_76210_Content_21 = {
    Text = "ক্লস্ট্রাম..."
  },
  AvgVideoCaption_76210_Content_22 = {
    Text = "সব কার্যক্রম স্বাভাবিক সীমার মধ্যেই চলছে।"
  },
  AvgVideoCaption_76210_Content_23 = {
    Text = "প্রিয় কুকুরছানা, আমি তোমার মস্তিষ্কের ভীষণ যত্ন নেব।"
  },
  AvgVideoCaption_76210_Content_24 = {
    Text = "হিপোক্যাম্পাসে ক্ষতি হয়ে যদি তুমি আর আমি ভাগ করে নেওয়া সেই মূল্যবান স্মৃতিচারণ হারিয়ে ফেলি, তবে তা ভীষণ অপচয় হবে।"
  },
  AvgVideoCaption_76210_Content_25 = {
    Text = "আমি এখনও সেই দিনটির কথা মনে করি, যেদিন প্রথম আমাদের দেখা হয়েছিল। তুমি আমাকে ডল ভেবেছিলে।"
  },
  AvgVideoCaption_76210_Content_26 = {
    Text = "তুমি মুখ তুলে আমার দিকে তাকিয়ে কাঁপা কাঁপা ভয়েসে আমাকে \"প্রফেসর ডল\" বলে ডেকেছিলে।"
  },
  AvgVideoCaption_76210_Content_27 = {
    Text = "আমি ভেবেছিলাম, আমি নাকি শুধু একটু গাম্ভীর্য নিয়ে চলি—কিন্তু শেষে বোঝা গেল, তুমি কেবলই ভয় পাচ্ছিলে অসমাপ্ত মাঠ-রিপোর্টের জন্য বকুনি খাবে বলে।"
  },
  AvgVideoCaption_76210_Content_28 = {
    Text = "তোমার মস্তিষ্কের কোন অংশে সেই স্মৃতি বাস করে?"
  },
  AvgVideoCaption_76210_Content_29 = {
    Text = "এখানে আছে?"
  },
  AvgVideoCaption_76210_Content_3 = {
    Text = "তোমার জন্য কি সত্যিই মাত্রা-সেতুবন্ধন এতটাই কঠিন?"
  },
  AvgVideoCaption_76210_Content_30 = {
    Text = "...নাকি এখানে?"
  },
  AvgVideoCaption_76210_Content_31 = {
    Text = "হাহা। আসলে তাতে বিশেষ কিছু যায় আসে না।"
  },
  AvgVideoCaption_76210_Content_32 = {
    Text = "কারণ ভাববার মতো আরও অনেক বেশি গুরুত্বপূর্ণ বিষয় রয়েছে।"
  },
  AvgVideoCaption_76210_Content_33 = {
    Text = "সেই একই দিনের শেষে, মিথাগের প্রফেসরের সঙ্গে কাঁধে কাঁধ মিলিয়ে, তুমিই নিজ হাতে আমাকে সিলমোহর করে দিয়েছিলে সেই অন্ধকার, আলোরহীন অতল গভীরে।"
  },
  AvgVideoCaption_76210_Content_34 = {
    Text = "চারটি অঙ্গই বাঁধনে আবদ্ধ, নড়াচড়া এতটাই সীমাবদ্ধ যে শুধু গড়িয়ে শোয়াটুকুও শ্বাসরুদ্ধকর লাগছিল..."
  },
  AvgVideoCaption_76210_Content_35 = {
    Text = "তুমি ভুলে গেলেও..."
  },
  AvgVideoCaption_76210_Content_36 = {
    Text = "আমি কোনোদিন, কোনোদিনও ভুলব না।"
  },
  AvgVideoCaption_76210_Content_37 = {
    Text = "প্রত্যাবর্তনহীন নরকে চিরন্তন বিনাশে পতিত হও।"
  },
  AvgVideoCaption_76210_Content_38 = {
    Text = "...এখন আমি ঠিক আছি।"
  },
  AvgVideoCaption_76210_Content_39 = {
    Text = "আমাকে ক্ষমা করো, মিথাগের কুকুরছানা।"
  },
  AvgVideoCaption_76210_Content_4 = {
    Text = "আমি ভেবেছিলাম ▼▼ টেকনোলজি তার সমগ্র অস্তিত্বই চেতনা-হস্তান্তরের গবেষণায় উৎসর্গ করেছে। এমন তুচ্ছ জটিলতা তো তুচ্ছই হওয়ার কথা।"
  },
  AvgVideoCaption_76210_Content_40 = {
    Text = "আমার নিজেকে এতটা বেপরোয়া হতে দেওয়া উচিত হয়নি।"
  },
  AvgVideoCaption_76210_Content_41 = {
    Text = "এখন তবে—আমি তোমার ব্রেইনস্টেম কেটে খুলে দেখব।"
  },
  AvgVideoCaption_76210_Content_42 = {
    Text = "তোমার হাইপোথ্যালামাসে নাগাল দাও, আর তোমার মিডব্রেনে প্রয়োজনীয় সমন্বয়গুলো করো..."
  },
  AvgVideoCaption_76210_Content_43 = {
    Text = "ওহ। তোমার স্নায়ুগুলো কাঁপছে।"
  },
  AvgVideoCaption_76210_Content_44 = {
    Text = "কী করুণ। আমি কি তোমাকে অবশ করার টিংচার প্রয়োগ করব?"
  },
  AvgVideoCaption_76210_Content_45 = {
    Text = "দুঃখজনক, এর জন্য এখন একটু বেশিই দেরি হয়ে গেছে।"
  },
  AvgVideoCaption_76210_Content_46 = {
    Text = "আরেকটু সহ্য করো। প্রায় শেষ, প্রায় শেষ —"
  },
  AvgVideoCaption_76210_Content_47 = {
    Text = "হুঁ, দেখি তো।"
  },
  AvgVideoCaption_76210_Content_48 = {
    Text = "কোথায় এটা?"
  },
  AvgVideoCaption_76210_Content_49 = {
    Text = "খুঁজে পেলাম।"
  },
  AvgVideoCaption_76210_Content_5 = {
    Text = "মনে হচ্ছে তোমাকে আমি অতিরিক্ত কৃতিত্ব দিয়েছিলাম।"
  },
  AvgVideoCaption_76210_Content_50 = {
    Text = "কার্যকলাপের স্তর পুনরুদ্ধার করতে, একমাত্রা বৈদ্যুতিক উদ্দীপনা প্রয়োজন হবে।"
  },
  AvgVideoCaption_76210_Content_51 = {
    Text = "আমি গিয়ে স্তব্ধতা-গানটা অনুসন্ধান করে আনি। নড়বে না, কেমন?"
  },
  AvgVideoCaption_76210_Content_52 = {
    Text = "তোমাকে এতক্ষণ প্রতীক্ষা করালাম, দুঃখী ছোট্টটি।"
  },
  AvgVideoCaption_76210_Content_53 = {
    Text = "তোমাকে যেন ঠিকমতো অনুভব করাতে পারি..."
  },
  AvgVideoCaption_76210_Content_54 = {
    Text = "অন্ধকার আর ভারী, আমারটার মতোই... কালি-কালো..."
  },
  AvgVideoCaption_76210_Content_55 = {
    Text = "এখন। আমরা শুরু করব সর্বনিম্ন স্তর থেকে।"
  },
  AvgVideoCaption_76210_Content_56 = {
    Text = "আমি মৃত্যুকে কার্যকরী হতে বেশি পছন্দ করি—একেবারে তাৎক্ষণিক হলে তো আরও ভালো।"
  },
  AvgVideoCaption_76210_Content_57 = {
    Text = "কিন্তু এই মুহূর্তে তোমার সত্যিকারের আস্বাদন করা প্রয়োজন। আমি এই সুযোগ অপচয় করব না।"
  },
  AvgVideoCaption_76210_Content_58 = {
    Text = "যেদিন প্রথম ফলকটি হাতে পেলাম, আমি ওটাকে নিছক এক জটিল ভাঁওতা বলে উড়িয়ে দিয়েছিলাম।"
  },
  AvgVideoCaption_76210_Content_59 = {
    Text = "তবু, আমি তো তার প্রথম লাইনটুকুও প্রায় পড়িনি।"
  },
  AvgVideoCaption_76210_Content_6 = {
    Text = "কোনো সমস্যা নেই। আমি নিজেই সামলে নেব।"
  },
  AvgVideoCaption_76210_Content_60 = {
    Text = "না—অর্ধেক লাইন।"
  },
  AvgVideoCaption_76210_Content_61 = {
    Text = "এতেই হয়ে গেল। আমি সঙ্গে সঙ্গেই বুঝেছিলাম—এটা নিঃসন্দেহে আসল বস্তু।"
  },
  AvgVideoCaption_76210_Content_62 = {
    Text = "এক প্রবল উচ্ছ্বাসের ঢেউ আমাকে ভাসিয়ে নিয়ে গেল।"
  },
  AvgVideoCaption_76210_Content_63 = {
    Text = "আমি তোমাকে সেই অনুভূতিটা বর্ণনা করি। ঠিক এটাই তুমি এখন অনুভব করছ।"
  },
  AvgVideoCaption_76210_Content_64 = {
    Text = "প্রায় অদৃশ্য এক পক্ষাঘাত, ফেইন্ট আর উৎসহীন, যেন শূন্য থেকে এসে ধীরে ধীরে ঢুকে পড়ছে।"
  },
  AvgVideoCaption_76210_Content_65 = {
    Text = "কোনো সতর্কবার্তা নেই। কোনো বিপদের আভাস নেই। উল্টো, প্রায় সুখকরই লাগছিল..."
  },
  AvgVideoCaption_76210_Content_66 = {
    Text = "অবশ্যই লাগছিল। এই বিশ্বের সত্য—যে চূড়ান্ত উত্তরের জন্য আমি সবকিছু ব্যয় করেছি—মনে হচ্ছিল অবশেষে নাগালের মধ্যে চলে এসেছে।"
  },
  AvgVideoCaption_76210_Content_67 = {
    Text = "মধুর টানে অসহায় কোনো প্রাণীর মতো, আমি পড়ে চললাম, লালসায়, উদ্‌গ্রীবে, বিন্দুমাত্র বিরতি না নিয়ে।"
  },
  AvgVideoCaption_76210_Content_68 = {
    Text = "ধাপে ধাপে, আরও গভীরে ফাঁদের মাঝে..."
  },
  AvgVideoCaption_76210_Content_69 = {
    Text = "আর আমি পড়ে গেলাম।"
  },
  AvgVideoCaption_76210_Content_7 = {
    Text = "মিথাগের কুকুরছানা, এটাকে তোমার সম্মান বলে বিবেচনা করো।"
  },
  AvgVideoCaption_76210_Content_70 = {
    Text = "একটা ফাঁদ, বিশেষভাবে আমার জন্য পাতা—এই দাম্ভিক, আত্মধার্মিক প্রতিভার জন্য।"
  },
  AvgVideoCaption_76210_Content_71 = {
    Text = "হ্যাঁ। সেই ফলকের একেবারে কেন্দ্রে, এক ফাঁদ বহুদিন ধরে প্রতীক্ষা করছিল, ধৈর্যশীল আর নীরব।"
  },
  AvgVideoCaption_76210_Content_72 = {
    Text = "আর আমি সোজা তার দিকেই হেঁটে গিয়েছিলাম, আনন্দে কাঁদতে কাঁদতে।"
  },
  AvgVideoCaption_76210_Content_73 = {
    Text = "আমি আসলে কী পড়ছি তা বুঝে ওঠার আগেই, অনেক দেরি হয়ে গিয়েছিল।"
  },
  AvgVideoCaption_76210_Content_74 = {
    Text = "আমি সব জানতাম। আমি উত্তর জানতাম। আমি ▼▼ জানতাম!!"
  },
  AvgVideoCaption_76210_Content_75 = {
    Text = "তুমি কি তা অনুভব করতে পারছ?"
  },
  AvgVideoCaption_76210_Content_76 = {
    Text = "এই অসহনীয়, অস্থি-মজ্জা ভেদ করা পেইন। এই অসহ্য হতাশা।"
  },
  AvgVideoCaption_76210_Content_77 = {
    Text = "যে ধরনের হতাশা মস্তিষ্ককে ভেঙে চুরমার করে—ঘন কালো, পরম।"
  },
  AvgVideoCaption_76210_Content_78 = {
    Text = "...আমাকে ক্ষমা করো, মিথাগের বাচ্চা। আমি আবার নিজেকে হারিয়ে ফেলেছিলাম।"
  },
  AvgVideoCaption_76210_Content_79 = {
    Text = "তবে তুমি নিশ্চিন্তে বিশ্রাম নিতে পারো। পদ্ধতিটা যতই অমার্জিত হোক, মৌলিক সক্রিয়তার মান অবশ্যই পূর্ণ হয়েছে।"
  },
  AvgVideoCaption_76210_Content_8 = {
    Text = "নির্দিষ্ট সমস্যাটি শনাক্ত করা হয়েছে। তুমি যে মস্তিষ্কের জারের কার্যস্তর বেছে নিয়েছ, তা কোনো মিথাগ রক্ষকের চেতনা টিকিয়ে রাখার জন্য যথেষ্ট নয়।"
  },
  AvgVideoCaption_76210_Content_80 = {
    Text = "আমি এখন সেন্সরটি সংযুক্ত করছি।"
  },
  AvgVideoCaption_76210_Content_81 = {
    Text = "শিগগিরই, তুমি এই জগতে প্রবেশ করবে।"
  },
  AvgVideoCaption_76210_Content_82 = {
    Text = "তাহলে আমরা একসাথে অপেক্ষা করব, সেই মুহূর্তটির জন্য যখন তুমি চোখ মেলবে। ভাবছি—তুমি কীভাবে মুখোমুখি হবে, যা তুমি দেখতে পাবে?"
