  AvgVideoCaption_84327_Content_50 = {
    Text = "কিন্তু তার ভেতরে—দ্য নটিলাসের সঙ্গে ডুবে যাচ্ছে অন্ধকারের গভীরে।"
  },
  AvgVideoCaption_84327_Content_51 = {
    Text = "যেকোনো আত্মাকে উন্মাদ করার জন্য যথেষ্ট।"
  },
  AvgVideoCaption_84327_Content_52 = {
    Text = "আমাকেও… অন্তর্ভুক্ত করে…"
  },
  AvgVideoCaption_84327_Content_53 = {
    Text = "মৃত হলেও, আমার আত্মা এই জাহাজে আটকে আছে।"
  },
  AvgVideoCaption_84327_Content_54 = {
    Text = "আমি জলদস্যুটাকে বাঁচিয়েছি, আর এখন প্রেতাত্মারাও আমাকে তাড়া করছে।"
  },
  AvgVideoCaption_84327_Content_55 = {
    Text = "আমি দ্য নটিলাসের প্রত্যাবর্তন দেখি…"
  },
  AvgVideoCaption_84327_Content_56 = {
    Text = "আর আমি দেখি সেটাকে ডুবে যেতে…"
  },
  AvgVideoCaption_84327_Content_57 = {
    Text = "প্রথমে, যুক্তি অটুট ছিল।"
  },
  AvgVideoCaption_84327_Content_58 = {
    Text = "ভ্রম এবং বাস্তবতা আলাদা ছিল।"
  },
  AvgVideoCaption_84327_Content_59 = {
    Text = "যতক্ষণ না…"
  },
  AvgVideoCaption_84327_Content_6 = {
    Text = "যখন দ্য নটিলাস অতল-এর আরও গভীরে তলিয়ে যাচ্ছিল..."
  },
  AvgVideoCaption_84327_Content_60 = {
    Text = "আমি এটা শুনেছি... আমি তাঁকে শুনেছি..."
  },
  AvgVideoCaption_84327_Content_61 = {
    Text = "তিনি আমাদের ডাকছেন!"
  },
  AvgVideoCaption_84327_Content_62 = {
    Text = "হারিয়ে যাওয়াদের, তিনি পথপ্রদর্শক।"
  },
  AvgVideoCaption_84327_Content_63 = {
    Text = "আকুল আকাঙ্ক্ষার, তিনি উত্তর দেন।"
  },
  AvgVideoCaption_84327_Content_64 = {
    Text = "হ্যাঁ! আমার পথপ্রদর্শক হোন! আমাকে গ্রহণ করুন!"
  },
  AvgVideoCaption_84327_Content_65 = {
    Text = "মহান প্রভু, আমাকে লেমুরিয়ায় নিয়ে চলুন... আপনার ঐশ্বরিক রাজ্যে!"
  },
  AvgVideoCaption_84327_Content_66 = {
    Text = "যেখানে আমি পাব শাশ্বত আনন্দ, অনন্ত জীবন!"
  },
  AvgVideoCaption_84327_Content_67 = {
    Text = "আমি স্বদেশে যাব! আমি স্বদেশে আসছি!"
  },
  AvgVideoCaption_84327_Content_68 = {
    Text = "সত্যিই, রালফ ঠিক বলেছিলেন:"
  },
  AvgVideoCaption_84327_Content_69 = {
    Text = "\"কোনো মরণশীল মন সমুদ্রের গভীরতা পরিমাপ করতে পারে না।\""
  },
  AvgVideoCaption_84327_Content_7 = {
    Text = "সত্যি বলতে, আমি জলদস্যুদের ঘৃণা করি।"
  },
  AvgVideoCaption_84327_Content_70 = {
    Text = "তাই যখন সেই দানবীয় শহরটি জেগে উঠল,"
  },
  AvgVideoCaption_84327_Content_71 = {
    Text = "আমি একে প্রলাপের ছলনা বলে মনে করেছিলাম।"
  },
  AvgVideoCaption_84327_Content_72 = {
    Text = "শব্দ বা নামের অতীত এক শহর,"
  },
  AvgVideoCaption_84327_Content_73 = {
    Text = "সমুদ্রতলে ছড়িয়ে থাকা এর বৃদ্ধ দীপ্তি।"
  },
  AvgVideoCaption_84327_Content_74 = {
    Text = "সেখানে অন্ধকারের মাঝে, এটি ঘুমিয়ে ছিল—প্রতীক্ষায়।"
  },
  AvgVideoCaption_84327_Content_75 = {
    Text = "নীরব। রোগী।"
  },
  AvgVideoCaption_84327_Content_76 = {
    Text = "আমাদের জন্য প্রতীক্ষা, ধরা-পড়া মাছিদের জন্য, যেন আমরা গিয়ে পড়ি তার জালে।"
  },
  AvgVideoCaption_84327_Content_77 = {
    Text = "লেমুরিয়া!"
  },
  AvgVideoCaption_84327_Content_78 = {
    Text = "এটাই লেমুরিয়া!"
  },
  AvgVideoCaption_84327_Content_79 = {
    Text = "তিনি ডাকছেন! তিনি ডাকছেন!"
  },
  AvgVideoCaption_84327_Content_8 = {
    Text = "যারা-ই জাহাজের নিরাপদ পথকে হুমকি দেয়, তারা-ই আমার শত্রু।"
  },
  AvgVideoCaption_84327_Content_80 = {
    Text = "ফিরে যাও! যেও না!"
  },
  AvgVideoCaption_84327_Content_81 = {
    Text = "...সে কথা শোনেনি। এভাবেই আমার আগে শেষ যাত্রীর মৃত্যু হয়েছিল।"
  },
  AvgVideoCaption_84327_Content_82 = {
    Text = "শুধু হাতির দাঁতের মূর্তিটিই অবশিষ্ট ছিল।"
  },
  AvgVideoCaption_84327_Content_83 = {
    Text = "আমি এখন সুস্থ মস্তিষ্কের নির্বাচনটি জানি..."
