  AvgVideoCaption_84327_Content_84 = {
    Text = "কিন্তু..."
  },
  AvgVideoCaption_84327_Content_85 = {
    Text = "একজন দিকনির্দেশকের কর্তব্য হলো সমুদ্রকে জানা।"
  },
  AvgVideoCaption_84327_Content_86 = {
    Text = "যখন মনের মানচিত্র মিথ্যা বলে,"
  },
  AvgVideoCaption_84327_Content_87 = {
    Text = "একজনকে অবশ্যই সংশোধন করতে হবে—পালানো নয়।"
  },
  AvgVideoCaption_84327_Content_88 = {
    Text = "<Red:তাহলে, এটার কাছে যাও>"
  },
  AvgVideoCaption_84327_Content_89 = {
    Text = "সত্যের সন্ধানে, আমাকে অবশ্যই..."
  },
  AvgVideoCaption_84327_Content_9 = {
    Text = "কিন্তু..."
  },
  AvgVideoCaption_84327_Content_90 = {
    Text = "আমাকে ভুলটা জানতে হবে। আমাকে তার প্রকৃতি অনুধাবন করতে হবে।"
  },
  AvgVideoCaption_84327_Content_91 = {
    Text = "অতএব, আমাকে হেঁটে যেতে হবে এই স্থানে, যেখানে এক দেবতা তন্দ্রায় নিমগ্ন।"
  },
  AvgVideoCaption_84327_Content_92 = {
    Text = "<Red:তাই, এটির সাড়া দাও>"
  },
  AvgVideoCaption_84327_Content_93 = {
    Text = "পৃথিবীর কোনো পথই আনন্দের দিকে নিয়ে যায় না।"
  },
  AvgVideoCaption_84327_Content_94 = {
    Text = "কেবল আত্মসমর্পণকারীরাই দেবত্বের ঝলক দেখতে পায়।"
  },
  AvgVideoCaption_84327_Content_95 = {
    Text = "<Red:তাই, এটির কাছে আত্মসমর্পণ করো!>"
  },
  AvgVideoCaption_84327_Content_96 = {
    Text = "<Red:সব কিছু উৎসর্গ করো!>"
  },
  AvgVideoCaption_84327_Content_97 = {
    Text = "তারপর—নিবেদিত কবিতার পর—আমি দেখলাম..."
  },
  AvgVideoCaption_84327_Content_98 = {
    Text = "যা নক্ষত্রপুঞ্জকেও তুচ্ছ করে, নামহীন, আকারহীন..."
  },
  AvgVideoCaption_84327_Content_99 = {
    Text = "\"কোনো মরণশীল মন সমুদ্রের গভীরতা পরিমাপ করতে পারে না।\""
  },
  AvgVideoCaption_90244_Content_1 = {
    Text = "হা… হা…"
  },
  AvgVideoCaption_90244_Content_10 = {
    Text = "কাটা দাগগুলো গভীর… তোমার পালকগুলো রক্তে জড়িয়ে একসাথে লেগে গেছে।"
  },
  AvgVideoCaption_90244_Content_100 = {
    Text = "পাণ্ডুলিপিতে লেখা এত জায়গা, যেগুলো আমরা কখনও দেখিনি। আমি সেখানে যেতে চাই।"
  },
  AvgVideoCaption_90244_Content_101 = {
    Text = "আমরা একদিন যাব। আমি এ বিষয়ে নিশ্চিত।"
  },
  AvgVideoCaption_90244_Content_102 = {
    Text = "অবশেষে, নাইট রাজকুমারীকে তার রাজ্যে প্রত্যাবর্তন করাল।"
  },
  AvgVideoCaption_90244_Content_103 = {
    Text = "তাদের স্বাগত জানাতে রাস্তাজুড়ে ফুলের বৃষ্টি নেমে এলো।"
  },
  AvgVideoCaption_90244_Content_104 = {
    Text = "তার নাম গৌরবের সাথে সারা দেশে বিস্তার লাভ করল।"
  },
  AvgVideoCaption_90244_Content_105 = {
    Text = "আহ। তাহলে এই ব্যাপার।"
  },
  AvgVideoCaption_90244_Content_106 = {
    Text = "আমি সবসময় ভাবি, গল্পের সমাপ্তি হওয়ার পর কী ঘটে।"
  },
  AvgVideoCaption_90244_Content_107 = {
    Text = "ভাই, তোমার কী মনে হয় নাইটের কী পরিণতি হয়েছিল?"
  },
  AvgVideoCaption_90244_Content_108 = {
    Text = "সে কি গৌরব, ধনসম্পদ, আর রাজকুমারীর ভালোবাসা অর্জন করেছিল?"
  },
  AvgVideoCaption_90244_Content_109 = {
    Text = "আমি জানি না..."
  },
  AvgVideoCaption_90244_Content_11 = {
    Text = "আমি আগে ময়লা পরিষ্কার করে নিই।"
  },
  AvgVideoCaption_90244_Content_110 = {
    Text = "তবে অন্তত সে গৌরব অর্জন করেছিল।"
  },
  AvgVideoCaption_90244_Content_111 = {
    Text = "তারপর, এত দূর থেকে রাজকুমারীকে বাঁচানোর পর,"
  },
  AvgVideoCaption_90244_Content_112 = {
    Text = "রাজা নিশ্চয়ই তাকে পুরস্কৃত করেছিলেন, তাই না?"
  },
  AvgVideoCaption_90244_Content_113 = {
    Text = "সত্যি, রাজাকে কৃপণ বলে মনে হয় না।"
  },
  AvgVideoCaption_90244_Content_114 = {
    Text = "সে তাকে নিয়ে দুর্গ থেকে পালিয়েছিল, ঘুরে বেড়িয়েছিল সেই সব দেশে—"
  },
  AvgVideoCaption_90244_Content_115 = {
    Text = "হয়তো রাজকুমারীও তার প্রেমে পড়েছিল?"
  },
  AvgVideoCaption_90244_Content_116 = {
    Text = "হুম... হতে পারে।"
  },
  AvgVideoCaption_90244_Content_117 = {
    Text = "যদিও নাইট দাবি করেছিল যে তার কিছুই চাই না,"
  },
  AvgVideoCaption_90244_Content_118 = {
    Text = "তবুও সে সবকিছুই পেয়েছিল।"
  },
  AvgVideoCaption_90244_Content_119 = {
    Text = "সাহসী মানুষরা সত্যিই... শেষমেশ... সবকিছুর... মালিক হয়..."
  },
  AvgVideoCaption_90244_Content_12 = {
    Text = "…ব্যথা করছে, তাই না? দুঃখিত… আমি আরও কোমল হবো।"
  },
  AvgVideoCaption_90244_Content_120 = {
    Text = "\"(সে ঘুমিয়ে আছে... এই ক’দিনের পালিয়ে বেড়ানো নিশ্চয়ই তাকে সম্পূর্ণ ক্লান্ত করে দিয়েছে।)\""
  },
  AvgVideoCaption_90244_Content_121 = {
    Text = "(এত পালক নষ্ট হয়ে গেল... আহ, এটা তো এখনো অক্ষত আছে।)"
  },
  AvgVideoCaption_90244_Content_122 = {
    Text = "(আমি এটা রেখে দিচ্ছি—হয়তো পরে পলাক্সকে গলার হার বানাবো।)"
  },
  AvgVideoCaption_90244_Content_123 = {
    Text = "(চাঁদটা এত গোল, নক্ষত্রপুঞ্জ এত উজ্জ্বল...)"
  },
  AvgVideoCaption_90244_Content_124 = {
    Text = "(একদম বইয়ের মতো... সাহসীরা কি সত্যিই সবকিছু পেয়ে যায়?)"
  },
  AvgVideoCaption_90244_Content_125 = {
    Text = "(গল্পগুলো তো আর মিথ্যে হতে পারে না... তাই না?)"
  },
  AvgVideoCaption_90244_Content_126 = {
    Text = "(শুভরাত্রি, নাইট পলাক্স।)"
  },
  AvgVideoCaption_90244_Content_13 = {
    Text = "ঠ-ঠিক আছে।"
  },
  AvgVideoCaption_90244_Content_14 = {
    Text = "পরিবর্তনের আচার অনুষ্ঠানের সঙ্গে তুলনা করলে... যখন তারা আমাকে কেটে খুলেছিল,"
  },
  AvgVideoCaption_90244_Content_15 = {
    Text = "আর আমার অঙ্গপ্রত্যঙ্গে চিহ্ন খোদাই করেছিল... তার পাশে এটা কিছুই না।"
  },
  AvgVideoCaption_90244_Content_16 = {
    Text = "…হ্যাঁ। সবসময়ই তুমি-ই ছিলে, যে সবচেয়ে বেশি যন্ত্রণা সহ্য করেছ।"
  },
  AvgVideoCaption_90244_Content_17 = {
    Text = "(ধুর, কথাটা বলা উচিত হয়নি আমার...)"
  },
  AvgVideoCaption_90244_Content_18 = {
    Text = "এসব এখন অতীত, ভাই।"
  },
  AvgVideoCaption_90244_Content_19 = {
    Text = "সেই সময়, আমাদের কোনো কিছুর ওপরই মতামত ছিল না। কিন্তু এখন... আমরা মুক্ত!"
  },
  AvgVideoCaption_90244_Content_2 = {
    Text = "দানবটির আর এখানে আমাদের তাড়া করা উচিত নয়।"
  },
  AvgVideoCaption_90244_Content_20 = {
    Text = "দয়া করে, পাণ্ডুলিপি থেকে তোমার কোনো একটা গল্প আবার শোনাও।"
  },
  AvgVideoCaption_90244_Content_21 = {
    Text = "যেমন তুমি প্রতিটি আচার অনুষ্ঠানের পর শোনাতে। তোমার গল্প শুনলেই পেইন মিলিয়ে যায়।"
  },
  AvgVideoCaption_90244_Content_22 = {
    Text = "ঠিক আছে"
  },
  AvgVideoCaption_90244_Content_23 = {
    Text = "\"তাহলে... আমি তোমাকে সেই কিংবদন্তি নাইটের অভিযানের কাহিনি শোনাই।\""
  },
  AvgVideoCaption_90244_Content_24 = {
