  AvgVideoCaption_98516_Content_10 = {
    Text = "আমরা পৌঁছে গেছি।"
  },
  AvgVideoCaption_98516_Content_11 = {
    Text = "@1@2-এর আচার অনুষ্ঠানের স্থান—অনিক্স বলিদানের ভূমি।"
  },
  AvgVideoCaption_98516_Content_12 = {
