  },
  AvgVideoCaption_98516_Content_13 = {
    Text = "দেখি কী পাওয়া যায়..."
  },
  AvgVideoCaption_98516_Content_14 = {
    Text = "ভেতরটা ফাঁপা মোমের পুতুল, নাড়িভুঁড়ি সব চেঁছে ফেলা হয়েছে।"
