  },
  AvgVideoCaption_98516_Content_20 = {
    Text = "ওরা কি চামড়া ছাড়িয়ে নিয়ে পেশিগুলোকে দগদগে লোহার ছাপ দিয়ে একসাথে জুড়ে দিয়েছে?"
