  },
  AvgVideoCaption_98516_Content_26 = {
    Text = "ওরা কি ভেতরে তরল ঢুকিয়ে নাড়িভুঁড়োকে নরম করে, তারপর সবকিছু একটা থলেতে গুঁজে দিয়েছে?"
