  AvgVideoCaption_98516_Content_29 = {
    Text = "ওরা তো... LT-13-এর সেই তিনটি অপ্রাপ্তবয়স্ক বাচ্চা।"
  },
  AvgVideoCaption_98516_Content_3 = {
    Text = "হেহ, এতেই প্রমাণ হয় তোমার খ্যাতি কতটা পোক্ত, বড় আপা।"
