  AvgVideoCaption_98516_Content_36 = {
    Text = "বড্ড বেশি খেলা করে ফেলেছি।"
  },
  AvgVideoCaption_98516_Content_37 = {
    Text = "পথ চেনার জন্য অন্তত একজনকে বাঁচিয়ে রাখা উচিত ছিল।"
  },
  AvgVideoCaption_98516_Content_38 = {
    Text = "...উঁহু, থাক, যা হোক। আজ এখানে থেকে কেউ জীবিত বেরোচ্ছে না। ধীরে সুস্থে সময় নিয়ে কাজ করলেই চলবে।"
