  AvgVideoCaption_98516_Content_42 = {
    Text = "বুঝেছি।"
  },
  AvgVideoCaption_98516_Content_43 = {
    Text = "কথা দিচ্ছি, তোর এই উৎসর্গ বৃথা যাবে না।"
  },
  AvgVideoCaption_98516_Content_44 = {
    Text = "ঘ্যানঘ্যান বন্ধ কর।"
  },
  AvgVideoCaption_98516_Content_45 = {
    Text = "আমি যখন বলেছি তুই শেষ, তার মানে তুই শেষ।"
  },
  AvgVideoCaption_98516_Content_46 = {
    Text = "পরের উৎসবটা হবে তোর স্মরণসভা।"
  },
  AvgVideoCaption_98516_Content_47 = {
    Text = "নিজের একটা ছবি সঙ্গে আনতে ভুলিস না যেন।"
  },
  AvgVideoCaption_98516_Content_48 = {
    Text = "ধুর ছাই, রক্স, তুই কোথায়?!"
  },
  AvgVideoCaption_98516_Content_49 = {
    Text = "রক্সের শেষ সংকেত এখানেই বিচ্ছিন্ন হয়ে গেছে..."
  },
  AvgVideoCaption_98516_Content_5 = {
    Text = "তাই নাকি? তোমার দিকে দেখো, হঠাৎ কেমন যেন সাবলীল হয়ে গেছো।"
