  AvgVideoCaption_98516_Content_54 = {Text = "কী?!"},
  AvgVideoCaption_98516_Content_55 = {
    Text = "'নব প্রভাত'-এর বিরুদ্ধাচরণকারী পাষণ্ড!"
  },
  AvgVideoCaption_98516_Content_56 = {
    Text = "তুই আমাদের প্রভুর বেদির খোরাক হবি!"
  },
  AvgVideoCaption_98516_Content_57 = {
    Text = "মূর্খ অপবিত্রকারীরা... রক্স আর ক্লেয়ার, তাই না?"
  },
  AvgVideoCaption_98516_Content_58 = {
    Text = "তোমার মাংসই হবে আমার ধর্মানুষ্ঠানের ক্যানভাস—"
  },
  AvgVideoCaption_98516_Content_59 = {
