  },
  AvgVideoCaption_98516_Content_62 = {
    Text = "ওই বাচ্চার আত্মা ইতিমধ্যেই আমার কাছে ফিরে এসেছে।"
  },
  AvgVideoCaption_98516_Content_63 = {
    Text = "তাছাড়া, ওর নাম রক্স নয়।"
  },
  AvgVideoCaption_98516_Content_64 = {
    Text = "আর আমার নাম যে ক্লেয়ার নয়, সেটা নরকের দিব্যি দিয়ে বলতে পারি।"
  },
  AvgVideoCaption_98516_Content_65 = {
    Text = "না-না!"
  },
  AvgVideoCaption_98516_Content_66 = {
    Text = "কীভাবে?!"
  },
  AvgVideoCaption_98516_Content_67 = {
    Text = "ওই শক্তি নিয়ে, তুমি কেন—"
  },
  AvgVideoCaption_98516_Content_68 = {
    Text = "অবশ্যই, তুই যা চাস তোকে সেটাই দেওয়ার জন্য।"
  },
  AvgVideoCaption_98516_Content_69 = {
    Text = "এটা কি তোর প্রিয় নয়?"
  },
  AvgVideoCaption_98516_Content_7 = {
    Text = "আরে থামো, \"ক্লেয়ার,\""
  },
  AvgVideoCaption_98516_Content_70 = {
    Text = "শিকারের চোখেমুখে নিরাশার ছাপ দেখতে তুই খুব ভালোবাসিস, তাই না?"
  },
  AvgVideoCaption_98516_Content_71 = {
    Text = "হ্যাঁ, ঠিক যেমনটা এখন তোর মুখে ফুটে উঠেছে।"
  },
  AvgVideoCaption_98516_Content_72 = {
    Text = "আআআআআআহ্!"
  },
  AvgVideoCaption_98516_Content_73 = {
    Text = "হাঁহ, বরং আমাকে ধন্যবাদ দেওয়া উচিত তোমাদের! উল্লাস করো। আজ আমি একটু দয়ালু মেজাজে আছি।"
  },
  AvgVideoCaption_98516_Content_74 = {
    Text = "তোর মতো আবর্জনাকে যন্ত্রণা দিয়ে কী যে শান্তি পাওয়া যায়।"
  },
  AvgVideoCaption_98516_Content_75 = {
    Text = "পুরস্কার হিসেবে, তোমরা উপভোগ করবে এক প্রিমিয়াম মানের যন্ত্রণা,"
  },
  AvgVideoCaption_98516_Content_76 = {
    Text = "আক্রোশ আর কামনায় উদ্বেল হয়ে উঠছে!"
  },
  AvgVideoCaption_98516_Content_77 = {
    Text = "তোমাদের সব হাড় গুঁড়িয়ে দেব, তারপর শরীর থেকে অর্ধেক খণ্ডাংশ টেনে বার করব।"
  },
  AvgVideoCaption_98516_Content_78 = {
    Text = "ওই হাড়ের টুকরোগুলো আর তোমাদের চোখের বল একসাথে পিষে, আবার গুঁজে দেব কোটরের ভেতর।"
